using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check warnings too
var warnings = build.FindChildrenRecursive<Warning>();
Console.WriteLine($"=== Warnings ({warnings.Count}) ===");
foreach (var w in warnings)
{
    var proj = w.GetNearestParent<Project>();
    Console.WriteLine($"  [{proj?.Name}] {w.Code}: {w.Text}");
}
Console.WriteLine();

// Check for MSB errors (project dependency failures)
var messages = build.FindChildrenRecursive<Message>();
var failMessages = messages.Where(m => m.Text != null && (m.Text.Contains("failed") || m.Text.Contains("not build"))).ToList();
Console.WriteLine($"=== Failure-related messages ({failMessages.Count}) ===");
foreach (var m in failMessages.Take(20))
{
    var proj = m.GetNearestParent<Project>();
    Console.WriteLine($"  [{proj?.Name}] {m.Text}");
}
EOF

