using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Get all distinct project instances and their actual success
var projects = build.FindChildrenRecursive<Project>();
var projByName = projects.GroupBy(p => p.Name).Where(g => g.Key != null && g.Key.EndsWith(".csproj"));
foreach (var g in projByName)
{
    var anyErrors = g.SelectMany(p => p.FindChildrenRecursive<Error>()).ToList();
    Console.WriteLine($"{g.Key}: {anyErrors.Count} direct error(s)");
    foreach (var e in anyErrors)
        Console.WriteLine($"  {e.Code} @ {e.File}:{e.LineNumber} - {e.Text}");
}
EOF

